//! `hyb generate` joins several `.hy` files into ONE Go package. The Hybrid
//! preludes (`option`/`some`, `set`, `hy_pop`) are package-level
//! declarations, so emitting them into every generated file broke the
//! package as soon as two files used one: `hy_pop redeclared in this
//! block`, `option redeclared`, `method option.unwrap already declared`.
//! They now go to one generated `hybrid_prelude.hy.go` per directory.

use std::fs;
use std::path::PathBuf;
use std::process::{Command, Output};

struct Module(PathBuf);

impl Module {
    fn new(tag: &str) -> Self {
        let root = std::env::temp_dir().join(format!(
            "hyb-generate-prelude-{}-{}",
            tag,
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let m = Self(root);
        m.write("go.mod", "module example.com/demo\n\ngo 1.26\n");
        m.write(
            "main.go",
            "package main\n\nimport \"fmt\"\n\nfunc main() {\n\tfmt.Println(First(), Second())\n}\n",
        );
        m
    }

    fn write(&self, name: &str, text: &str) {
        fs::write(self.0.join(name), text).unwrap();
    }

    fn hyb(&self, args: &[&str]) -> Output {
        Command::new(env!("CARGO_BIN_EXE_hyb"))
            .args(args)
            .current_dir(&self.0)
            .output()
            .expect("run hyb")
    }

    fn go_run(&self) -> Output {
        Command::new("go")
            .args(["run", "."])
            .current_dir(&self.0)
            .output()
            .expect("run go")
    }
}

impl Drop for Module {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn assert_success(out: &Output) {
    assert!(
        out.status.success(),
        "stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
}

const A_HY: &str = "pub fn first() int {\n    var o option[int] = some(1)\n    s := set[int]{}\n    s.insert(5)\n    xs := []int{10, 20}\n    return o.unwrap() + len(s) + xs.pop()\n}\n";
const B_HY: &str = "pub fn second() int {\n    var o option[int] = some(2)\n    s := set[int]{}\n    s.insert(6)\n    xs := []int{30, 40}\n    return o.unwrap() + len(s) + xs.pop()\n}\n";

#[test]
fn two_files_using_every_prelude_build_as_one_package() {
    let m = Module::new("build");
    m.write("a.hy", A_HY);
    m.write("b.hy", B_HY);
    assert_success(&m.hyb(&["generate", "."]));

    let prelude = fs::read_to_string(m.0.join("hybrid_prelude.hy.go")).unwrap();
    assert!(prelude.starts_with("// Code generated by hyb"), "{prelude}");
    for decl in ["type option[", "type set[", "func hy_pop["] {
        assert_eq!(prelude.matches(decl).count(), 1, "{decl} once:\n{prelude}");
        for f in ["a.hy.go", "b.hy.go"] {
            let g = fs::read_to_string(m.0.join(f)).unwrap();
            assert!(
                !g.contains(decl),
                "{decl} must not be inlined into {f}:\n{g}"
            );
        }
    }

    let run = m.go_run();
    assert_success(&run);
    assert_eq!(String::from_utf8_lossy(&run.stdout), "22 43\n");
    assert_success(&m.hyb(&["generate", "--check", "."]));
}

#[test]
fn prelude_file_tracks_what_the_package_still_needs() {
    let m = Module::new("stale");
    m.write("a.hy", A_HY);
    m.write("b.hy", B_HY);
    assert_success(&m.hyb(&["generate", "."]));
    assert!(m.0.join("hybrid_prelude.hy.go").exists());

    // No file needs a prelude any more: --check reports the stale prelude,
    // a regenerate removes it, and the package still builds.
    m.write("a.hy", "pub fn first() int {\n    return 1\n}\n");
    m.write("b.hy", "pub fn second() int {\n    return 2\n}\n");
    let check = m.hyb(&["generate", "--check", "."]);
    assert!(!check.status.success());
    assert!(
        String::from_utf8_lossy(&check.stderr).contains("hybrid_prelude.hy.go"),
        "{}",
        String::from_utf8_lossy(&check.stderr)
    );
    assert_success(&m.hyb(&["generate", "."]));
    assert!(!m.0.join("hybrid_prelude.hy.go").exists());
    let run = m.go_run();
    assert_success(&run);
    assert_eq!(String::from_utf8_lossy(&run.stdout), "1 2\n");
}

#[test]
fn hand_written_prelude_file_is_never_overwritten() {
    let m = Module::new("handwritten");
    m.write("a.hy", A_HY);
    m.write("b.hy", B_HY);
    m.write("hybrid_prelude.hy.go", "package main\n\n// mine\n");
    let out = m.hyb(&["generate", "."]);
    assert!(!out.status.success());
    assert!(
        String::from_utf8_lossy(&out.stderr).contains("NOT hyb-generated"),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        fs::read_to_string(m.0.join("hybrid_prelude.hy.go")).unwrap(),
        "package main\n\n// mine\n"
    );
}

#[test]
fn a_hy_file_named_like_the_prelude_is_refused() {
    let m = Module::new("collide");
    m.write(
        "hybrid_prelude.hy",
        "pub fn first() int {\n    return 1\n}\n",
    );
    m.write("b.hy", B_HY);
    let out = m.hyb(&["generate", "."]);
    assert!(!out.status.success());
    assert!(
        String::from_utf8_lossy(&out.stderr).contains("rename it"),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
}
